<script setup>
import { t as tr, dateLabel } from './i18n.mjs'
import { computed, ref, watch } from 'vue'
import { Button, Badge } from 'frappe-ui'
import { ArrowUpRight, ArrowRight, Ship, Plane, PackageCheck, Factory, Wrench, Boxes, CalendarClock, CircleAlert, RefreshCw } from 'lucide-vue-next'
import { TODAY, fmt, openQty } from './domain.mjs'
import { dashboardData, money, percent, transitQty, unshippedQty } from './analytics.mjs'

const props=defineProps({orders:Array,shipments:Array,issues:Array,role:String})
const emit=defineEmits(['inspect','open-order','navigate','reset'])
const supplier=ref('全部供应商'), category=ref('全部分类'), chartMeasure=ref('qty')
const rows=computed(()=>props.orders.filter(o=>(supplier.value==='全部供应商'||o.supplier===supplier.value)&&(category.value==='全部分类'||o.type===category.value)))
const data=computed(()=>dashboardData(rows.value,props.shipments))
const activeIssues=computed(()=>props.issues.filter(i=>i.status!=='已解决'&&rows.value.some(o=>o.id===i.order)))
const dueBatches=computed(()=>data.value.batches.filter(s=>s.eta>=TODAY&&s.eta<='2026-09-15'))
const colors=['#196caa','#14a89a','#a0adbc']
const transportTotal=computed(()=>data.value.transport.reduce((n,t)=>n+t[chartMeasure.value],0))
const donut=computed(()=>{
  let start=0
  if(!transportTotal.value)return {background:'#e7edf3'}
  return {background:`conic-gradient(${data.value.transport.map((t,i)=>{const end=start+t[chartMeasure.value]/transportTotal.value*100;const stop=`${colors[i]} ${start}% ${end}%`;start=end;return stop}).join(',')})`}
})
function inspect(ids,label){emit('inspect',{ids,label})}
function inspectRows(records,label){inspect(records.map(o=>o.id),label)}
watch(()=>props.role,()=>{supplier.value='全部供应商'})
</script>

<template><div class="overview"><div class="ov-toolbar">
      <div class="ov-title-group"><h1>{{tr('总览看板')}}</h1><div class="ov-snapshot"><span class="ov-dot"></span><span class="ov-date">{{TODAY}} {{tr("· 演示业务日")}}</span></div></div>
      <div class="ov-filters">
        <select v-if="role==='buyer'" v-model="supplier" :aria-label="tr(&quot;总览供应商筛选&quot;)"><option :value="&quot;全部供应商&quot;">{{tr("全部供应商")}}</option><option :value="s" v-for="s in [...new Set(orders.map(o=>o.supplier))]" :key="s">{{tr(s)}}</option></select>
        <select v-model="category" :aria-label="tr(&quot;总览订单分类筛选&quot;)"><option :value="&quot;全部分类&quot;">{{tr("全部分类")}}</option><option :value="&quot;生产订单&quot;">{{tr("生产订单")}}</option><option :value="&quot;售后配件&quot;">{{tr("售后配件")}}</option></select>
        <span>{{tr("AUD · 件")}}</span>
        <Button variant="outline" @click="emit('reset')"><RefreshCw :size="14"/>{{tr('重置演示')}}</Button>
      </div>
    </div><div class="ov-kpis">
      <button class="ov-kpi" @click="inspectRows(data.open,'未完成订单')"><div class="ov-kpi-label">{{tr("未完成订单")}} <Boxes :size="19"/></div><strong>{{tr(data.poCount)}}<span>{{tr("张 PO")}}</span></strong><footer><span>{{tr("未交货值")}} <b>{{tr(money(data.openValue))}}</b></span><ArrowUpRight :size="17"/></footer></button>
      <button class="ov-kpi ov-kpi-featured" @click="inspectRows(rows.filter(o=>transitQty(o)>0),'在途订单')"><div class="ov-kpi-label">{{tr("在途数量")}} <Ship :size="20"/></div><strong>{{tr(fmt(data.transitQty))}}<span>{{tr("件")}}</span></strong><footer><span>{{tr("在途货值")}} <b>{{tr(money(data.transitValue))}}</b></span><ArrowUpRight :size="17"/></footer></button>
      <button class="ov-kpi" @click="inspectRows(rows.filter(o=>unshippedQty(o)>0),'尚未发运订单')"><div class="ov-kpi-label">{{tr("尚未发运")}} <Factory :size="19"/></div><strong>{{tr(fmt(data.unshippedQty))}}<span>{{tr("件")}}</span></strong><footer><span>{{tr("未发货值")}} <b>{{tr(money(data.openValue-data.transitValue))}}</b></span><ArrowUpRight :size="17"/></footer></button>
      <button class="ov-kpi" @click="inspectRows(rows.filter(o=>o.received>0),'有收货记录的订单')"><div class="ov-kpi-label">{{tr('已收货 · SAP')}}<PackageCheck :size="17"/></div><strong>{{fmt(data.receivedQty)}}<span>{{tr('件')}}</span></strong><footer><span>{{tr('已收货值')}} <b>{{money(data.receivedValue)}}</b></span><ArrowUpRight :size="14"/></footer></button><button class="ov-kpi ov-kpi-risk" @click="inspectRows(data.risk,'交期风险订单')"><div class="ov-kpi-label">{{tr("交期风险")}} <CalendarClock :size="19"/></div><strong>{{tr(data.risk.length)}}<span>{{tr("行")}}</span></strong><footer><span>{{tr("另有")}} <b>{{tr(data.unconfirmed.length)}} {{tr("行")}}</b> {{tr("尚待确认")}}</span><ArrowUpRight :size="17"/></footer></button>
    </div><div class="ov-summary-grid"><section class="ov-panel">
        <div class="ov-panel-title"><div><h2>{{tr("运输与履约")}}</h2></div><div class="ov-segment" :aria-label="tr(&quot;运输图表统计方式&quot;)"><button :aria-pressed="chartMeasure==='qty'" :class="{active:chartMeasure==='qty'}" @click="chartMeasure='qty'">{{tr("数量")}}</button><button :aria-pressed="chartMeasure==='value'" :class="{active:chartMeasure==='value'}" @click="chartMeasure='value'">{{tr("货值")}}</button></div></div>
        <div class="ov-mini-flow"><div class="ov-stack"> <i :style="{width:percent(data.unshippedQty,data.totalQty)+'%'}"></i><i :style="{width:percent(data.transitQty,data.totalQty)+'%'}"></i><i :style="{width:percent(data.receivedQty,data.totalQty)+'%'}"></i></div><div class="ov-flow-legend"><span><i></i>{{tr('未发')}} {{percent(data.unshippedQty,data.totalQty)}}%</span><span><i></i>{{tr('在途')}} {{percent(data.transitQty,data.totalQty)}}%</span><span><i></i>{{tr('已收')}} {{percent(data.receivedQty,data.totalQty)}}%</span></div></div><div class="ov-transport-heading"><h3>{{tr('在途运输分布')}}</h3><small>{{data.batches.length}} {{tr('个关联运输批次')}}</small></div><div class="ov-mode-bar" role="img" :aria-label="data.transport.map(t=>tr(t.mode)+': '+percent(t[chartMeasure],transportTotal)+'%').join(', ')"><i v-for="(t,i) in data.transport" :key="t.mode" :style="{width:percent(t[chartMeasure],transportTotal)+'%',background:colors[i]}"></i></div><div class="ov-mode-rows"><button v-for="(t,i) in data.transport" :key="t.mode" @click="inspect(t.ids,t.mode+'在途订单')"><span><i :style="{background:colors[i]}"></i>{{tr(t.mode)}} <small>{{percent(t[chartMeasure],transportTotal)}}%</small></span><b>{{fmt(t.qty)}} <small>{{tr('件')}}</small></b><strong>{{money(t.value)}}</strong></button></div>
        <div class="ov-freight"><span>{{tr("在途批次运费")}} <b>{{tr(money(data.freight))}}</b></span></div>
      </section><section class="ov-panel">
        <div class="ov-panel-title"><div><h2>{{tr("订单分类")}}</h2></div><span class="ov-tag">{{tr(data.open.length)}} {{tr("行")}}</span></div>
        <button v-for="(c,i) in data.categories" :key="c.type" class="ov-category-compact" :title="tr('其中在途')+' '+fmt(c.transit)+' '+tr('件')" @click="inspect(c.ids,c.type+' · 未完成')"><div><b>{{tr(c.type)}}</b><span>{{c.count}} {{tr('行')}} · {{fmt(c.qty)}} {{tr('件')}}</span><strong>{{money(c.value)}}</strong></div><div class="ov-category-track"><i :style="{width:percent(c.count,data.open.length)+'%',background:colors[i]}"></i></div></button>

      <div class="ov-supplier-heading"><h3>{{tr('供应商协作概况')}}</h3><small>{{tr('已确认 / 未完成行')}}</small></div><button v-for="s in data.suppliers" :key="s.name" class="ov-mini-supplier" @click="inspect(s.ids,s.name+' · 未完成')"><span>{{s.name}}</span><div><i :style="{width:percent(s.confirmed,s.count)+'%'}"></i></div><b>{{s.confirmed}} / {{s.count}}</b><ArrowUpRight :size="13"/></button></section><section class="ov-panel ov-ageing">
        <div class="ov-panel-title"><div><h2>{{tr("未完成订单账龄")}}</h2></div></div>
        <div class="ov-table-scroll"><table><thead><tr><th>{{tr("账龄")}}</th><th>{{tr("生产")}}</th><th>{{tr("售后")}}</th><th>{{tr("合计 / 行")}}</th><th class="right">{{tr("未交货值")}}</th></tr></thead><tbody><tr v-for="a in data.ageing" :key="a.label"><td><button @click="inspect(a.ids,'账龄 '+a.label)">{{tr(a.label)}} <ArrowUpRight :size="12"/></button></td><td>{{tr(a.production)}}</td><td>{{tr(a.parts)}}</td><td><div class="ov-age-cell"><span :style="{width:percent(a.count,Math.max(...data.ageing.map(a=>a.count),1))+'%'}"></span><b>{{tr(a.count)}}</b></div></td><td class="right">{{tr(money(a.value))}}</td></tr></tbody><tfoot><tr><td>{{tr("合计")}}</td><td>{{tr(data.categories[0].count)}}</td><td>{{tr(data.categories[1].count)}}</td><td>{{tr(data.open.length)}}</td><td class="right">{{tr(money(data.openValue))}}</td></tr></tfoot></table></div>
      </section></div><div class="ov-detail-grid"><section class="ov-panel ov-eta-panel">
      <div class="ov-panel-title"><div><h2>{{tr("在途到仓计划")}} <span class="ov-inline-count">{{tr(data.batches.length)}}</span></h2></div><Button variant="outline" @click="emit('navigate','shipments')">{{tr("全部物流")}} <ArrowRight :size="14"/></Button></div>
      <div class="ov-table-scroll"><table><thead><tr><th>{{tr("运输 / 订单")}}</th><th>{{tr("当前位置 → 目的地")}}</th><th class="right">{{tr("在途数量")}}</th><th class="right">{{tr("货值 / 运费")}}</th><th>{{tr("预计到仓")}}</th><th></th></tr></thead><tbody><tr v-for="s in data.batches.slice(0,3)" :key="s.id"><td><button class="ov-po" @click="emit('open-order',s.orderRecord)"><component :is="s.mode==='海运'?Ship:Plane" :size="14"/>{{s.orderRecord.po}} / {{s.orderRecord.item}}</button><small>{{tr(s.mode)}} · {{s.ref}}</small></td><td>{{s.locationUserEntered?s.location:tr(s.location)}}<small>→ {{tr(s.to)}}</small></td><td class="right">{{tr(fmt(s.outstanding))}} {{tr("件")}}</td><td class="right"><b>{{money(s.goodsValue)}}</b><small>{{tr("运费")}} {{money(s.freight||0)}}</small></td><td><strong>{{tr(dateLabel(s.eta))}}</strong><small :class="{'ov-warning':s.eta>s.originalEta}">{{tr(s.eta>s.originalEta?'较首次 ETA 延后 '+Math.round((Date.parse(s.eta)-Date.parse(s.originalEta))/86400000)+' 天':'按首次 ETA')}}</small></td><td><button class="ov-open" :aria-label="tr('查看订单 '+s.orderRecord.po)" @click="emit('open-order',s.orderRecord)"><ArrowUpRight :size="18"/></button></td></tr><tr v-if="!data.batches.length"><td colspan="6" class="ov-empty">{{tr("当前筛选范围没有在途运输批次。")}}</td></tr></tbody></table></div>
    <div class="ov-eta-caption"><span>{{tr('按 ETA 排序，展示最近 3 批；完整记录见全部物流。')}}</span><span>{{tr('未来 7 天预计到仓')}} <b>{{dueBatches.length}} {{tr('批 /')}} {{fmt(dueBatches.reduce((n,s)=>n+s.outstanding,0))}} {{tr('件')}}</b></span></div></section><section class="ov-panel ov-action-panel">
        <div class="ov-panel-title"><div><h2>{{tr("需要关注")}}</h2></div><CircleAlert :size="20"/></div>
        <button @click="inspectRows(data.unconfirmed,'待供应商确认')"><span>{{tr("待供应商确认")}}</span><b>{{tr(data.unconfirmed.length)}} {{tr("行")}}</b><ArrowRight :size="16"/></button>
        <button @click="inspectRows(data.risk,'交期风险订单')"><span>{{tr("承诺晚于需求")}}</span><b>{{tr(data.risk.length)}} {{tr("行")}}</b><ArrowRight :size="16"/></button>
        <button @click="emit('navigate','exceptions')"><span>{{tr("当前筛选未关闭异常")}}</span><b>{{tr(activeIssues.length)}} {{tr("项")}}</b><ArrowRight :size="16"/></button>
        <button @click="emit('navigate',role==='buyer'?'data':'exceptions')"><span>{{tr('待核对的数据问题')}}</span><b>{{activeIssues.filter(i=>i.category==='数据问题').length}} {{tr('项')}}</b><ArrowRight :size="16"/></button>

      </section></div><details class="ov-definitions"><summary>{{tr('统计口径')}} · {{tr('AUD · 件')}}<span>{{tr('点击指标可查看订单明细')}}</span></summary><p class="ov-footnote">{{tr("模拟数据 · 所有金额为 AUD 示例采购货值，按数量 × 单价计算，不含运费及税费；全部物料暂统一为“件”。本页随当前角色、筛选和演示操作更新，未接入 SAP 或实际价格。")}}</p><p>{{tr('从下单日至演示业务日 · 账龄不等于延期')}} · {{tr('当前未完成订单；确认包含部分数量承诺')}} · {{tr('异常入口展示当前角色的全部待办。')}}</p></details></div></template>
